source('code/00_config.R');suppressPackageStartupMessages({library(openxlsx);library(xml2)})
checks<-list();add<-function(test,ok,detail=''){checks[[length(checks)+1L]]<<-data.table(test=test,status=if(isTRUE(ok))'PASS'else'FAIL',detail=as.character(detail))}
m<-readRDS(path('metadata/analysis_metadata.rds'));list0<-rd(path('INTERNAL_RESTRICTED/original_clinical/SSB_three_group_sample_list.tsv'));fr<-rd(path('results/regional_Ri_fractions.tsv'));den<-rd(path('metadata/library_denominators.tsv'));ch<-rd(path('metadata/library_counts_by_chromosome.tsv'))
add('Final cohort and author-list identity',nrow(m)==261&&uniqueN(m$sample_id)==261&&setequal(m$sample_id,list0$sample_id),'HC144 / AD89 / Other28')
add('Group allocation identity',all(m$final_group==list0$group[match(m$sample_id,list0$sample_id)]))
add('Complete-covariate count',sum(m$complete_primary)==259)
add('Numeric disease MMSE count',sum(!is.na(m[source_group=='Disease-source',mmse_observed_min]))==100)
add('No hard exclusions in analysis',!any(m$hard_excluded))
chr<-ch[,.(sum_D=sum(N)),by=sample_id];dd<-merge(den,chr,by='sample_id');add('All-contig D reconstructed',all(dd$D==dd$sum_D))
B<-mean(fr[region=='GENE',gene_annotation_count_sum]);add('Ri fixed common reference',all(abs(fr$GENE_batch_mean-B)<1e-12*B)&&all(abs(fr$Ri-fr$gene_annotation_count_sum/B)<1e-12)&&abs(mean(fr[region=='GENE',Ri])-1)<1e-12,paste(format(B,digits=16),'relative tolerance1e-12 for decimal TSV serialization'))
for(s in SPACES){z<-readRDS(path('matrices',paste0(s,'_inputs.rds')));add(paste(s,'matrix identities'),!anyDuplicated(z$annotation$gene_id)&&setequal(colnames(z$counts),m$sample_id));add(paste(s,'integer valid per-gene counts'),all(is.finite(z$counts))&&all(z$counts>=0)&&all(z$counts==floor(z$counts))&&all(sweep(z$counts,2,z$D,'<=')!=0));L<-sweep(z$counts,2,z$D,'/')*1e10;add(paste(s,'LPKM formula every cell'),all(abs(z$lpkm-L)<=1e-12*pmax(1,abs(L))));add(paste(s,'unshared counts'),all(z$unshared_counts>=0)&all(z$unshared_counts<=z$counts));total<-colSums(z$counts);q<-fr[region==s];add(paste(s,'Ri numerator every participant'),all(total[q$sample_id]==q$gene_annotation_count_sum));q0<-rd(path('audit',paste0(s,'_coordinate_conversion.tsv')));add(paste(s,'rebuilt source union'),q0$cached_union_rebuilt_comparison=='PASS');rm(z,L);gc()}

splits<-list.files(path('audit'),pattern='_split_audit[.]tsv$',full.names=TRUE);add('All 22 model split manifests',length(splits)==22)
leakage<-list();pairs<-rd(path('metadata/matched_pairs.tsv'))
for(f in splits){x<-rd(f);stopifnot(nrow(x)==100);for(i in seq_len(nrow(x))){tr<-strsplit(x$training_ids[i],'|',fixed=TRUE)[[1]];va<-strsplit(x$validation_ids[i],'|',fixed=TRUE)[[1]];te<-strsplit(x$outer_test_ids[i],'|',fixed=TRUE)[[1]];bad<-length(intersect(tr,va))+length(intersect(tr,te))+length(intersect(va,te));pairbad<-0L;if(x$task[i]=='matched'){pmap<-setNames(pairs$matched_pair,pairs$sample_id);pairbad<-length(intersect(pmap[tr],pmap[va]))+length(intersect(pmap[tr],pmap[te]))+length(intersect(pmap[va],pmap[te]))};leakage[[length(leakage)+1L]]<-data.table(task=x$task[i],region=x$region[i],repetition=x$repetition[i],outer_fold=x$outer_fold[i],inner_fold=x$inner_fold[i],participant_overlap=bad,pair_overlap=pairbad)}}
leakage<-rbindlist(leakage);wr(leakage,path('audit/nested_validation_independent_audit.tsv'));add('Training / validation / outer test disjoint',all(leakage$participant_overlap==0));add('Matched pairs stay in one fold',all(leakage$pair_overlap==0))
o<-rd(path('results/models/participant_mean_OOF.tsv'));add('Five OOF predictions per participant/task',all(o$predictions==5)&&!anyDuplicated(o[,.(sample_id,task,region)])&&all(o$probability>=0&o$probability<=1))
pf<-rd(path('results/models/performance.tsv'));calcauc<-function(y,p){n1<-sum(y==1);n0<-sum(y==0);(sum(rank(p)[y==1])-n1*(n1+1)/2)/(n1*n0)};u<-o[,.(recalculated_auc=calcauc(y,probability)),by=.(task,region)];u<-merge(u,pf,by=c('task','region'));add('AUC orientation and recalculation',all(abs(u$AUC-u$recalculated_auc)<1e-12),'No flipping; no minimum AUC gate')

registry<-readRDS(path('audit/figure_registry.rds'));ids<-names(registry$captions);members<-unlist(c(registry$main,registry$supplementary_layout));add('All composite panels registered',all(members%in%ids));add('Four main figures',length(registry$main)==4)
files<-unlist(lapply(ids,function(id)path('figures/panels',paste0(id,c('.pdf','.svg','.tiff')))));add('Every registered panel has vector / raster files',all(file.exists(files)),length(ids))
for(id in ids){for(f in c('plot_data.tsv','statistics.tsv','participants.tsv','legend_EN_ZH.md','results_and_legend_EN_ZH.md'))add(paste(id,f),file.exists(path('source_data',id,f)));add(paste(id,'R entry'),file.exists(path('code/panels',paste0(id,'.R'))));add(paste(id,'Excel source'),file.exists(path('excel/panels',paste0(id,'_source_data.xlsx'))));pa<-rd(path('source_data',id,'participants.tsv'));if(id!='FigS1A')add(paste(id,'participants within approved cohort'),all(pa$sample_id%in%m$sample_id));svg<-read_xml(path('figures/panels',paste0(id,'.svg')));add(paste(id,'editable SVG text'),length(xml_find_all(svg,'//*[local-name()="text"]'))>0)}
pdfs<-c(unlist(lapply(names(registry$main),function(n)path('figures/main',paste0(n,'.pdf')))),unlist(lapply(names(registry$supplementary_layout),function(n)path('figures/supplementary',paste0('Figure_',n,'.pdf')))))
if(nzchar(Sys.which('identify'))){tifs<-c(path('figures/panels',paste0(ids,'.tiff')),sub('[.]pdf$','.tiff',pdfs));dpi<-rbindlist(lapply(tifs,function(f){z<-system2('identify',c('-ping','-format',shQuote('%x %y %[units]'),shQuote(f)),stdout=TRUE);data.table(file=substring(f,nchar(ROOT)+2),resolution=z[1],PASS=grepl('^600 600 PixelsPerInch$',z[1]))}));wr(dpi,path('audit/TIFF_600dpi_audit.tsv'));add('All TIFFs actual600dpi',all(dpi$PASS))}
fontrows<-list();for(f in pdfs){z<-system2('pdffonts',shQuote(f),stdout=TRUE);fontrows[[f]]<-data.table(file=substring(f,nchar(ROOT)+2),report=paste(z,collapse='\n'));add(paste(basename(f),'embedded editable fonts'),any(grepl('TrueType',z))&&!any(grepl('Type 3',z)))};wr(rbindlist(fontrows),path('audit/PDF_font_audit.tsv'))
add('Observed editable Word Table1',file.exists(path('tables/Table1.docx')));doc<-read_xml(unz(path('manuscript/Manuscript_EN.docx'),'word/document.xml'));eq<-length(xml_find_all(doc,'//*[local-name()="oMath"]'));add('Editable native Word equations',eq>=12,eq)
alltext<-readLines(path('manuscript/Manuscript_EN.md'));add('No stale cohort numbers in manuscript',!any(grepl('294 participants|292 participants|150 disease-source|128 disease|7953|7,953|98 genes',alltext)))
add('Primary EXON and actual count retained',any(grepl('360',alltext))&&any(grepl('EXON',alltext)))
add('Primary Gene average Ri exactly one',rd(path('audit/metric_validation.tsv'))$mean_GENE_Ri==1)
ex<-rd(path('audit/Excel_panel_roundtrip.tsv'));add('Every panel Excel identity checked',setequal(ex$panel,ids)&&all(ex$status=='PASS'))
for(s in SPACES)add(paste(s,'full matrix Excel checked'),file.exists(path('audit',paste0('Excel_raw_',s,'_validation.tsv'))))
result<-rbindlist(checks);wr(result,path('audit/FINAL_QA_checks.tsv'));savebook(list(QA_checks=result,Fold_disjointness=leakage,Recalculated_AUC=u),path('audit/FINAL_QA_report.xlsx'));capture.output(sessionInfo(),file=path('audit/R_sessionInfo.txt'))
packages<-unique(c('data.table','matrixStats','IRanges','S4Vectors','limma','glmnet','Matrix','ggplot2','patchwork','svglite','ragg','openxlsx','officer','flextable','xml2','httr','jsonlite','stringr','scales','rlang'));wr(data.table(package=packages,version=vapply(packages,function(x)as.character(packageVersion(x)),character(1))),path('audit/package_version_lock.tsv'))
if(any(result$status=='FAIL')){print(result[status=='FAIL']);stop('QA failed; package cannot be marked complete')}
logstage('quality_assurance',paste('PASS',nrow(result),'checks,',length(ids),'panels,',nrow(leakage),'nested splits; editable equations',eq))
